/* Token definitions for a parser generated by yacc.  */

#define NUMBER 257
#define NAME 258
#define ASSIGNOP 259
#define EQOP 260
#define RELOP 261
#define SHIFTOP 262
#define MULOP 263
#define OR 264
#define AND 265
#define BOR 266
#define BXOR 267
#define BAND 268
#define PLUS 269
#define MINUS 270
#define NOT 271
#define TILDE 272
#define QUEST 273
#define COLON 274
#define COMMA 275
#define LPAR 276
#define RPAR 277
#define PREINC 278
#define PREDEC 279
#define POSTINC 280
#define POSTDEC 281
#define OTHER 282

#if !defined(YYSTYPE) && !defined(YYSTYPE_IS_DECLARED)
typedef union YYSTYPE {
    AVal a;
    long v;
    const char *op;
    char *s;
    ANum num;
    ATern t;
    AHead h;
} YYSTYPE;
#define YYSTYPE_IS_DECLARED 1
#endif
extern YYSTYPE yylval;
int yyparse(void);
